When a fixture requests another fixture, the other fixture is executed first.
So if fixture a requests fixture b, fixture b will execute first,
because a depends on b and can't operate without it. Even if a
doesn't need the result of b, it can still request b if it needs to make
sure it is executed after b.

例如：

import pytest

@pytest.fixture
def order():
return []

@pytest.fixture
def a(order):
order.append("a")

@pytest.fixture
def b(a, order):
order.append("b")

@pytest.fixture
def c(a, b, order):
order.append("c")

@pytest.fixture
def d(c, b, order):
order.append("d")

@pytest.fixture
def e(d, b, order):
order.append("e")

@pytest.fixture
def f(e, order):
order.append("f")

@pytest.fixture
def g(f, c, order):
order.append("g")

def test_order(g, order):
assert order == ["a", "b", "c", "d", "e", "f", "g"]

